// 365 year-progress stars in the map void. Packed as x,y,shape triples.
// shape: 0=dot 1=pair 2=cross 3=diamond. Order is the fill sequence.
export const STAR_N = 365;
// One literal rather than "..." + "..." pieces, so launch concatenates nothing.
let STAR_HEX = "";
// Pebble Round 2 sky positions for the same stars, as x,y pairs; shapes stay
// by index. Generated by scripts/gen-round-stars.cjs --write: the hex lattice
// used to be laid out on the watch at every launch.
let ROUND_STAR_HEX = "";

export const STAR_X = new Uint8Array(STAR_N);
export const STAR_Y = new Uint8Array(STAR_N);
export const STAR_SHAPE = new Uint8Array(STAR_N);

// The ASCII codes of a hex string. XS on the watch keeps no string index
// cache, so hex.charCodeAt(i) walks the string from its start and a decode
// loop over it is O(n^2); ArrayBuffer.fromString copies the bytes in one pass.
function hexChars(hex) {
	if (typeof ArrayBuffer.fromString === "function")
		return new Uint8Array(ArrayBuffer.fromString(hex));
	const chars = new Uint8Array(hex.length);
	for (let i = 0; i < hex.length; i++)
		chars[i] = hex.charCodeAt(i);
	return chars;
}

{
	const c = hexChars(STAR_HEX);
	for (let i = 0, o = 0; i < STAR_N; i++, o += 6) {
		const b0 = c[o], b1 = c[o + 1], b2 = c[o + 2], b3 = c[o + 3], b4 = c[o + 4], b5 = c[o + 5];
		STAR_X[i] = ((b0 < 58 ? b0 - 48 : b0 - 87) << 4) | (b1 < 58 ? b1 - 48 : b1 - 87);
		STAR_Y[i] = ((b2 < 58 ? b2 - 48 : b2 - 87) << 4) | (b3 < 58 ? b3 - 48 : b3 - 87);
		STAR_SHAPE[i] = ((b4 < 58 ? b4 - 48 : b4 - 87) << 4) | (b5 < 58 ? b5 - 48 : b5 - 87);
	}
}
STAR_HEX = null;

// Moves the stars to their Round 2 sky positions.
export function useRoundStars() {
	const c = hexChars(ROUND_STAR_HEX);
	for (let i = 0, o = 0; i < STAR_N; i++, o += 4) {
		const b0 = c[o], b1 = c[o + 1], b2 = c[o + 2], b3 = c[o + 3];
		STAR_X[i] = ((b0 < 58 ? b0 - 48 : b0 - 87) << 4) | (b1 < 58 ? b1 - 48 : b1 - 87);
		STAR_Y[i] = ((b2 < 58 ? b2 - 48 : b2 - 87) << 4) | (b3 < 58 ? b3 - 48 : b3 - 87);
	}
	ROUND_STAR_HEX = null;
}

export function dayOfYear(now) {
	const start = Date.UTC(now.getFullYear(), 0, 1);
	const today = Date.UTC(now.getFullYear(), now.getMonth(), now.getDate());
	return (((today - start) / 86400000) | 0) + 1;
}

export function litStarCount(now) {
	const n = dayOfYear(now);
	return n > STAR_N ? STAR_N : n;
}

// Indexes of the four solstice and equinox stars, ascending.
export function seasonStars(year) {
	const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0 ? 1 : 0;
	return [78 + leap, 171 + leap, 264 + leap, 354 + leap];
}

export function isSeasonStar(index, year) {
	const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0 ? 1 : 0;
	const day = index + 1;
	return day === 79 + leap || day === 172 + leap || day === 265 + leap || day === 355 + leap;
}
